import urllib.request, concurrent.futures, hashlib, json
pin='53770948682c40bd460b39830d4e0f0fd3a4b868'
base='https://raw.githubusercontent.com/openmm/openmm/'+pin+'/'
urls={ 'benchmark':base+'examples/benchmark.py','pdb':base+'examples/5dfr_solv-cube_equil.pdb','amber':base+'wrappers/python/openmm/app/data/amber99sb.xml','water':base+'wrappers/python/openmm/app/data/tip3p.xml','openmm':'https://pypi.org/pypi/openmm/8.2.0/json','plugin':'https://pypi.org/pypi/OpenMM-CUDA-12/8.2.0/json','tag':'https://api.github.com/repos/openmm/openmm/git/ref/tags/8.2.0','platform':'https://docs.openmm.org/8.2.0/userguide/library/04_platform_specifics.html'}
def get(k,u):
 try:
  b=urllib.request.urlopen(u, timeout=30).read(); out={'name':k,'url':u,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
  if k=='benchmark':
   s=b.decode(); a=s.find(\"if test == 'pme'\"); out['pme_excerpt']=s[a:a+6500]; out['options']=[l for l in s.splitlines() if 'add_option' in l or 'LangevinMiddle' in l]
  elif k in ('openmm','plugin'):
   j=json.loads(b); out['requires_python']=j['info'].get('requires_python');out['requires_dist']=j['info'].get('requires_dist');out['linux_wheels']=[{'filename':x['filename'],'sha256':x['digests']['sha256'],'size':x['size']} for x in j['urls'] if 'manylinux' in x['filename']]
  elif k=='tag':out['tag']=json.loads(b)
  elif k=='platform':
   s=b.decode();a=s.find('DeterministicForces');out['determinism']=s[a:a+1700]
  elif k=='pdb':out['atom_records']=sum(l.startswith((b'ATOM  ',b'HETATM')) for l in b.splitlines())
  return out
 except Exception as e:return {'name':k,'error':str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
 for r in ex.map(lambda x:get(*x),urls.items()):print(json.dumps(r))
PY"

